public BigDecimal accruedInterest(BigDecimal principal, BigDecimal annualRate,
                                  LocalDate from, LocalDate to) {
    // Проверка входных данных: если сумма кредита (principal) меньше или равна нулю,
    // либо конечная дата (to) не позже начальной (from), то проценты не начисляются.
    // Возвращаем ноль, так как начисление невозможно или не имеет смысла.
    if (principal.signum() <= 0 || !to.isAfter(from)) {
        return BigDecimal.ZERO;
    }

    // Инициализируем переменную для накопления общей суммы начисленных процентов.
    BigDecimal total = BigDecimal.ZERO;

    // Цикл по каждому дню в периоде от даты 'from' (включительно) до даты 'to' (исключительно).
    // Для каждого дня рассчитывается ежедневная сумма процентов.
    for (LocalDate d = from; d.isBefore(to); d = d.plusDays(1)) {
        // Определяем количество дней в году для текущей даты d.
        // Если год високосный, то 366 дней, иначе 365.
        // Это важно для точного расчета ежедневной ставки.
        int daysInYear = d.isLeapYear() ? 366 : 365;

        // Рассчитываем сумму процентов за один день:
        // 1. Умножаем сумму кредита (principal) на годовую процентную ставку (annualRate).
        // 2. Делим результат на количество дней в году (daysInYear), чтобы получить дневную сумму.
        // 3. Используем точность 10 знаков после запятой и округление HALF_UP для промежуточных вычислений,
        //    чтобы минимизировать ошибки округления при накоплении.
        BigDecimal daily = principal.multiply(annualRate)
            .divide(BigDecimal.valueOf(daysInYear), 10, RoundingMode.HALF_UP);

        // Добавляем рассчитанную дневную сумму процентов к общей накопленной сумме.
        total = total.add(daily);
    }

    // Возвращаем итоговую сумму начисленных процентов, округленную до 2 знаков после запятой
    // (стандартный формат для денежных сумм) с использованием режима округления HALF_UP.
    return total.setScale(2, RoundingMode.HALF_UP);
}
