public static void ValidateEntry(IReadOnlyList<Posting> postings)
{
    // Проверяем, что в проводке (бухгалтерской записи) есть минимум две строки.
    // Это необходимо, так как любая корректная бухгалтерская проводка должна содержать
    // как минимум один дебет и один кредит (двойная запись).
    if (postings.Count < 2)
        throw new ArgumentException("Entry must have at least two postings");

    // Инициализируем переменные для накопления сумм по дебету и кредиту.
    decimal debit = 0m, credit = 0m;

    // Проходим по каждой строке проводки (постингу) для проверки и накопления сумм.
    foreach (var p in postings)
    {
        // Проверяем, что сумма в строке положительная.
        // Нулевые или отрицательные суммы недопустимы в стандартных бухгалтерских проводках.
        if (p.Amount <= 0m)
            throw new ArgumentException($"Non-positive amount on account {p.Account}");

        // В зависимости от стороны (дебет или кредит) добавляем сумму к соответствующему итогу.
        if (p.Side == Side.Debit) debit += p.Amount;
        else credit += p.Amount;
    }

    // Проверяем баланс проводки: сумма дебетовых строк должна быть равна сумме кредитовых строк.
    // Это фундаментальное правило двойной бухгалтерии.
    if (debit != credit)
        throw new InvalidOperationException($"Unbalanced entry: debit {debit}, credit {credit}");

    // Проверяем, что все строки проводки используют одну и ту же валюту.
    // Смешивание валют в одной проводке обычно недопустимо, так как нарушает принцип
    // эквивалентности дебетовых и кредитовых сумм в одной единице измерения.
    if (postings.Select(p => p.Currency).Distinct().Count() > 1)
        throw new InvalidOperationException("Mixed currencies in one entry");
}
