// Transfer выполняет перевод средств между двумя счетами.
// Параметры:
//   - from: счет-отправитель
//   - to: счет-получатель
//   - amount: сумма перевода (в копейках/центах или другой минимальной единице)
// Возвращает ошибку, если перевод невозможен.
func (l *Ledger) Transfer(from, to *Account, amount int64) error {
	// Проверка валидности параметров перевода:
	// сумма должна быть положительной, и нельзя переводить средства самому себе.
	if amount <= 0 || from.ID == to.ID {
		return ErrInvalidTransfer
	}

	// Для предотвращения взаимной блокировки (deadlock) при одновременном
	// захвате мьютексов двух счетов, мы всегда блокируем их в одном и том же
	// порядке — по возрастанию ID.
	// first и second — это ссылки на счета, упорядоченные по ID.
	first, second := from, to
	if first.ID > second.ID {
		first, second = second, first
	}

	// Захватываем мьютекс первого (меньшего по ID) счета.
	// defer гарантирует, что мьютекс будет разблокирован при выходе из функции.
	first.mu.Lock()
	defer first.mu.Unlock()

	// Захватываем мьютекс второго (большего по ID) счета.
	// Так как мы всегда блокируем в порядке возрастания ID, это безопасно
	// и не приводит к deadlock даже при конкурентных вызовах Transfer.
	second.mu.Lock()
	defer second.mu.Unlock()

	// Проверяем, достаточно ли средств на счете-отправителе.
	// Используем from.Balance, так как from — это исходный счет-отправитель,
	// независимо от того, был ли он назначен как first или second.
	if from.Balance < amount {
		return fmt.Errorf("account %d: insufficient funds: have %d, need %d", from.ID, from.Balance, amount)
	}

	// Выполняем сам перевод: списываем сумму со счета-отправителя
	// и зачисляем её на счет-получатель.
	from.Balance -= amount
	to.Balance += amount

	// Возвращаем nil, так как перевод выполнен успешно.
	return nil
}
