export function invoiceTotals(lines: InvoiceLine[], vatRate: number) {
  // Проверяем, что ставка НДС находится в допустимом диапазоне от 0 до 1 (включительно).
  // Если ставка выходит за эти пределы, выбрасываем ошибку RangeError, так как это некорректное значение.
  if (vatRate < 0 || vatRate > 1) throw new RangeError(`vatRate out of range: ${vatRate}`);

  // Инициализируем переменные для накопления итоговых сумм:
  // net — сумма без НДС (нетто),
  // vat — сумма НДС.
  let net = 0;
  let vat = 0;

  // Проходим по каждой строке инвойса (позиции в счете).
  for (const line of lines) {
    // Пропускаем строки с некорректным количеством (меньше или равно нулю),
    // так как они не должны учитываться в итогах.
    if (line.qty <= 0) continue;

    // Рассчитываем сумму без НДС для текущей строки:
    // умножаем цену в копейках на количество и округляем результат до целого числа.
    const lineNet = Math.round(line.priceKop * line.qty);

    // Рассчитываем сумму НДС для текущей строки:
    // умножаем сумму без НДС на ставку НДС и округляем результат до целого числа.
    const lineVat = Math.round(lineNet * vatRate);

    // Добавляем рассчитанные значения к общим итоговым суммам.
    net += lineNet;
    vat += lineVat;
  }

  // Возвращаем объект с итогами:
  // net — общая сумма без НДС,
  // vat — общая сумма НДС,
  // gross — общая сумма с НДС (нетто + НДС).
  return { net, vat, gross: net + vat };
}
