/// Парсит строку с суммой в рублях и копейках (например, "123.45" или "-10.00")
/// и возвращает общую сумму в копейках как i64.
/// Возвращает ошибку в виде строки, если формат неверный или произошло переполнение.
pub fn parse_kopecks(s: &str) -> Result<i64, String> {
    // Удаляем пробелы по краям строки, чтобы избежать ошибок из-за лишних пробелов
    let s = s.trim();

    // Проверяем наличие знака минуса в начале строки.
    // Если он есть, отделяем его и запоминаем, что число отрицательное.
    // Если нет — считаем число положительным.
    let (neg, digits) = match s.strip_prefix('-') {
        Some(rest) => (true, rest),
        None => (false, s),
    };

    // Разделяем строку на целую часть (рубли) и дробную часть (копейки) по точке.
    // Если точки нет, считаем, что копеек 0.
    let (rub, kop) = digits.split_once('.').unwrap_or((digits, "0"));

    // Валидация формата:
    // 1. Целая часть не должна быть пустой (например, ".50" недопустимо).
    // 2. Дробная часть не должна содержать более 2 цифр (максимум 2 цифры для копеек).
    // 3. Все символы в обеих частях должны быть ASCII-цифрами (0-9).
    if rub.is_empty() || kop.len() > 2 || !rub.chars().chain(kop.chars()).all(|c| c.is_ascii_digit()) {
        return Err(format!("bad amount: {s}"));
    }

    // Дополняем строку копеек справа нулями до 2 символов (например, "5" -> "50", "" -> "00"),
    // затем парсим её в число.
    let kop: i64 = format!("{kop:0<2}").parse().map_err(|e| format!("{e}"))?;

    // Парсим целую часть (рубли) в число.
    let rub: i64 = rub.parse().map_err(|e| format!("{e}"))?;

    // Вычисляем общую сумму в копейках:
    // 1. Умножаем рубли на 100 (с проверкой на переполнение).
    // 2. Прибавляем копейки (с проверкой на переполнение).
    // Если произошло переполнение, возвращаем ошибку.
    let total = rub.checked_mul(100).and_then(|v| v.checked_add(kop)).ok_or("overflow")?;

    // Возвращаем результат: если был знак минуса, делаем сумму отрицательной.
    Ok(if neg { -total } else { total })
}
